import json
from pathlib import Path
import random
import logging

# OpenTelemetry imports
from opentelemetry import trace

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
tracer = trace.get_tracer(__name__) # Get tracer for this module

CONFIG_DIR = Path(__file__).parent / "configs"

class AgentConfig:
    """Handles loading, validation, and manipulation of agent configurations."""

    @tracer.start_as_current_span("AgentConfig.init")
    def __init__(self, config_path: Path):
        if not config_path.exists():
            raise FileNotFoundError(f"Configuration file not found: {config_path}")
        self.path = config_path
        with open(config_path, 'r') as f:
            self.data = json.load(f)
        self.validate()
        trace.get_current_span().set_attribute("config.path", str(config_path))
        trace.get_current_span().set_attribute("agent.id", self.data.get("agent_id", "unknown"))

    @tracer.start_as_current_span("AgentConfig.validate")
    def validate(self):
        """Basic validation of the config structure."""
        required_keys = ["agent_id", "version", "okr", "departments"]
        for key in required_keys:
            if key not in self.data:
                raise ValueError(f"Missing required key '{key}' in config {self.path}")
        if not isinstance(self.data["departments"], list):
            raise TypeError("'departments' must be a list.")
        trace.get_current_span().set_attribute("config.is_valid", True)


    def get(self, key, default=None):
        return self.data.get(key, default)

    def __repr__(self):
        return f"AgentConfig(path='{self.path}')"

@tracer.start_as_current_span("get_random_config")
def get_random_config() -> AgentConfig:
    """Selects a random configuration file from the configs directory."""
    config_files = list(CONFIG_DIR.glob("*.json"))
    if not config_files:
        raise FileNotFoundError(f"No configurations found in {CONFIG_DIR}")
    random_path = random.choice(config_files)
    logging.info(f"Performing morphogenesis: selected new config '{random_path.name}'")
    trace.get_current_span().set_attribute("config.selected_path", str(random_path))
    return AgentConfig(random_path)

@tracer.start_as_current_span("perform_crossover")
def perform_crossover(parent1_cfg: AgentConfig, parent2_cfg: AgentConfig) -> dict:
    """
    Performs 'structural allelic crossover' by merging two configurations.
    This is a simplistic implementation for demonstration.
    """
    logging.info(f"Performing crossover between {parent1_cfg.path.name} and {parent2_cfg.path.name}")

    span = trace.get_current_span()
    span.set_attribute("parent1.id", parent1_cfg.get("agent_id"))
    span.set_attribute("parent2.id", parent2_cfg.get("agent_id"))

    child_data = parent1_cfg.data.copy()

    # Crossover departments: take a mix from both parents
    p1_deps = {d['name']: d for d in parent1_cfg.get("departments", [])}
    p2_deps = {d['name']: d for d in parent2_cfg.get("departments", [])}

    combined_deps = {**p1_deps, **p2_deps}
    child_data["departments"] = list(combined_deps.values())[:7] # Enforce max departments

    # Crossover OKR from parent 2
    child_data["okr"] = parent2_cfg.get("okr")

    child_data["agent_id"] = f"child_of_{parent1_cfg.get('agent_id')}_{parent2_cfg.get('agent_id')}"
    child_data["version"] = f"{parent1_cfg.get('version')}+{parent2_cfg.get('version')}"

    logging.info(f"Created new child agent config: {child_data['agent_id']}")
    span.set_attribute("child.id", child_data["agent_id"])
    return child_data
